'use strict';

/**
 * Shared DynamoDB access. Uses the AWS SDK v3 bundled with the nodejs20.x runtime.
 */

const { DynamoDBClient } = require('@aws-sdk/client-dynamodb');
const { DynamoDBDocumentClient, BatchGetCommand, QueryCommand } = require('@aws-sdk/lib-dynamodb');
const { validationFailed } = require('../errors');

const doc = DynamoDBDocumentClient.from(new DynamoDBClient({}), {
    marshallOptions: { removeUndefinedValues: true },
});

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

/**
 * Fetches items by a single-attribute key. Dedupes ids, chunks by 100 and retries UnprocessedKeys
 * (max 5 tries with backoff). Returns a Map of id -> item (missing ids are absent).
 * `projection` is an optional list of attribute names; the key is always included.
 */
async function batchGetByIds(tableName, keyName, ids, projection) {
    const result = new Map();
    const unique = [...new Set((ids || []).filter((id) => id !== undefined && id !== null))];
    if (unique.length === 0) return result;

    let projectionParams = {};
    if (projection && projection.length) {
        const names = {};
        const attrs = [...new Set([keyName, ...projection])].map((attr, i) => {
            names[`#p${i}`] = attr;
            return `#p${i}`;
        });
        projectionParams = { ProjectionExpression: attrs.join(', '), ExpressionAttributeNames: names };
    }

    for (let i = 0; i < unique.length; i += 100) {
        let keys = unique.slice(i, i + 100).map((id) => ({ [keyName]: id }));
        for (let attempt = 0; keys.length > 0; attempt += 1) {
            if (attempt >= 5) throw new Error(`batchGetByIds: unprocessed keys remain for ${tableName}`);
            if (attempt > 0) await sleep(50 * 2 ** attempt);
            const res = await doc.send(
                new BatchGetCommand({ RequestItems: { [tableName]: { Keys: keys, ...projectionParams } } })
            );
            for (const item of (res.Responses && res.Responses[tableName]) || []) result.set(item[keyName], item);
            const unprocessed = res.UnprocessedKeys && res.UnprocessedKeys[tableName];
            keys = unprocessed && unprocessed.Keys ? unprocessed.Keys : [];
        }
    }
    return result;
}

/** Runs a Query and follows LastEvaluatedKey until all items are read. */
async function queryAll(params) {
    const items = [];
    let ExclusiveStartKey;
    do {
        const res = await doc.send(new QueryCommand({ ...params, ExclusiveStartKey }));
        items.push(...(res.Items || []));
        ExclusiveStartKey = res.LastEvaluatedKey;
    } while (ExclusiveStartKey);
    return items;
}

function encodeToken(lastEvaluatedKey) {
    if (!lastEvaluatedKey) return null;
    return Buffer.from(JSON.stringify(lastEvaluatedKey), 'utf8').toString('base64url');
}

/** Decodes a nextToken. Missing gives undefined; invalid throws 400 VALIDATION_FAILED. */
function decodeToken(token) {
    if (token === undefined || token === null || token === '') return undefined;
    try {
        const value = JSON.parse(Buffer.from(String(token), 'base64url').toString('utf8'));
        if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error('not an object');
        return value;
    } catch (err) {
        throw validationFailed([{ field: 'nextToken', message: 'nextToken is not valid' }]);
    }
}

module.exports = { doc, batchGetByIds, queryAll, encodeToken, decodeToken };
